SELECT CASE WHEN w.entry_quality_score >= 70 THEN '70+' WHEN w.entry_quality_score >= 60 THEN '60-69' WHEN w.entry_quality_score >= 55 THEN '55-59' WHEN w.entry_quality_score >= 50 THEN '50-54' ELSE '<50_or_0' END AS eq_band, COUNT(*) AS n, SUM(pp.realized_pnl < 0) AS losers, SUM(pp.status = 'STOPPED') AS stopped, SUM(pp.realized_pnl) AS net_pnl, AVG(pp.realized_pnl) AS avg_pnl FROM crypto_ai.paper_position pp JOIN crypto_ai.wallet_managed_position w ON w.symbol = pp.symbol AND w.opened_at BETWEEN pp.opened_at - INTERVAL 15 SECOND AND pp.opened_at + INTERVAL 15 SECOND WHERE pp.status IN ('CLOSED','STOPPED') GROUP BY eq_band ORDER BY eq_band LIMIT 10